// Attention scale 1/sqrt(dhead). rsqrtf is fine; keep it a constexpr-ish value
// computed once on host-visible compile (1/sqrt(32)).
__device__ __forceinline__ float attn_scale() { return rsqrtf((float)kDhead); }
