// PHASE-1 decoder L3-REAL scratch: the per-CTA grad-partial workspace + barrier
// counters + the int32 sizes/offsets task table (one task per parameter tensor,
// for the reduce + optimizer phases). The workspace is nCTA*total grad partials
// + nCTA loss partials; we size it for nCTA = #SMs (the launcher pins one CTA per
// SM). Persisted + reset per step like FusedScratch (the big workspace is zeroed
// IN-KERNEL by phase P0, so the host only resets the barrier/task counters here).
struct DecoderScratch {
 torch::Tensor g_next;        // int32 [1]
 torch::Tensor g_arrived;     // int32 [1] (unsigned-reinterpreted)
 torch::Tensor g_generation;  // int32 [1] (unsigned-reinterpreted)
 torch::Tensor sizes;         // int32 [kDecNumTensors] per-tensor numel
 torch::Tensor offsets;       // int32 [kDecNumTensors] per-tensor element offset
 torch::Tensor grad;          // float [total] reduced grad
 torch::Tensor workspace;     // float [nCTA*total + nCTA] partials + loss slots
 int n_ctas = 0;
};

inline DecoderScratch& decoder_scratch_for(const torch::Tensor& params) {
 static std::unordered_map<long long, DecoderScratch> cache;
 const long long dev_idx =
 params.device().is_cuda() ? static_cast<long long>(params.device().index())
 : -1LL;
 const long long key = dev_idx;   // one decoder shape per device (fixed total)
 auto it = cache.find(key);
 const int64_t total = sg::fused::sm90::kDecTotalElems;
 if (it == cache.end()) {
 int dev = params.device().is_cuda() ? params.device().index() : 0;
 int n_sms = 1;
 cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
 auto opts_i =
 torch::TensorOptions().device(params.device()).dtype(torch::kInt32);
 auto opts_f =
 torch::TensorOptions().device(params.device()).dtype(torch::kFloat32);
 DecoderScratch s;
 s.g_next = torch::zeros({1}, opts_i);
 s.g_arrived = torch::zeros({1}, opts_i);
 s.g_generation = torch::zeros({1}, opts_i);
 // Per-tensor sizes/offsets from the generated layout (single source of truth).
 // Host mirror of kDecSizes/kDecOffsets (the device __constant__ arrays are not
 // host-addressable, so we build the int32 tensors from the same values).
 auto sizes_cpu = torch::empty({sg::fused::sm90::kDecNumTensors},
 torch::TensorOptions().dtype(torch::kInt32));
 auto off_cpu = torch::empty({sg::fused::sm90::kDecNumTensors},
 torch::TensorOptions().dtype(torch::kInt32));
 int* sp = sizes_cpu.data_ptr<int>();
 int* op = off_cpu.data_ptr<int>();
 int acc = 0;
 // Rebuild from the host-side layout tables in decoder_layout.cuh's check ns.
 for (int i = 0; i < sg::fused::sm90::kDecNumTensors; ++i) {
 sp[i] = sg::fused::sm90::dec_layout_check::kSizes[i];
 op[i] = sg::fused::sm90::dec_layout_check::kOffsets[i];
 TORCH_CHECK(op[i] == acc, "decoder_layout host/device offset mismatch");
 acc += sp[i];
 }
 TORCH_CHECK((int64_t)acc == total, "decoder_layout host total mismatch");
 s.sizes = sizes_cpu.to(params.device());
 s.offsets = off_cpu.to(params.device());
 s.grad = torch::zeros({total}, opts_f);
 // workspace: nCTA*total partials + nCTA loss slots. Zeroed in-kernel (P0);
 // allocate (not zero) — the in-kernel P0 + the loss reduce overwrite it.
 s.workspace = torch::empty({(int64_t)n_sms * total + n_sms}, opts_f);
 s.n_ctas = n_sms;
 it = cache.emplace(key, std::move(s)).first;
 } else {
 it->second.g_next.zero_();
 it->second.g_arrived.zero_();
 it->second.g_generation.zero_();
 }
 return it->second;
}
#endif

